namespace mdemangler.datatype.modifier;




using mdemangler;
using mdemangler;

/**
 * This class represents the E, F, I portions of a modifier type within a Microsoft
 *  mangled symbol.
 */
// TODO: come up with a better class name... MDPointerModifier?  MDAddressModifier <--*** ?
public class MDEFIModifier : MDParsableItem {
	public static readonly char SPACE = ' ';

	public static string PTR64 = "__ptr64";
	private static readonly string UNALIGNED = "__unaligned";
	private static readonly string RESTRICT = "__restrict";

	// EFI Modifiers
	private bool isPointer64; // Can be pointer or reference
	private bool isUnaligned;
	private bool isRestrict;

	public MDEFIModifier(MDMang dmang) : base(dmang)
    {
	}

	private enum CvPrefix {
		_PTR64, _UNALIGNED, _RESTRICT
	}

	private List<CvPrefix> prefixList = new();

//	public MDEFIModifier() {
//		// use defaults
//	}

	public bool isPointer64() {
		return isPointer64;
	}

	public bool isUnaligned() {
		return isUnaligned;
	}

	public bool isRestrict() {
		return isRestrict;
	}

	/* @Override */
	protected void parseInternal() {
		bool prefixDone = false;
		while (!prefixDone) {
			switch (dmang.peek()) {
				case 'E':
					isPointer64 = true;
					prefixList.add(CvPrefix._PTR64);
					dmang.increment();
					break;
				case 'F':
					isUnaligned = true;
					prefixList.add(CvPrefix._UNALIGNED);
					dmang.increment();
					break;
				case 'I':
					isRestrict = true;
					prefixList.add(CvPrefix._RESTRICT);
					dmang.increment();
					break;
				default:
					prefixDone = true;
					break;
			}
		}
	}

	public string emit(StringBuilder builder) {
		StringBuilder left = new StringBuilder();
		StringBuilder right = new StringBuilder();

		foreach (CvPrefix p in prefixList) {
			switch (p) {
				case _UNALIGNED:
					left.insert(0, UNALIGNED + SPACE);
					break;
				default:
					break;
			}
		}
//		ListIterator<cvPrefix> li = prefixList.listIterator(prefixList.size());
//		while (li.hasPrevious()) {
//			cvPrefix p = li.previous();
		foreach (CvPrefix p in prefixList) {
			switch (p) {
				case _PTR64:
					right.append(SPACE + PTR64);
					break;
				case _RESTRICT:
					right.append(SPACE + RESTRICT);
					break;
				default:
					break;
			}
		}
		if ((builder.length() == 0) && (left.length() != 0) && (right.length() != 0)) {
			left.setLength(left.length() - 1);
		}
		builder.insert(0, left);
		if ((builder.length() != 0) && (builder.charAt(builder.length() - 1) == ' ') &&
			(right.length() != 0) && (right.charAt(0) == ' ')) {
			builder.setLength(builder.length() - 1);
		}
		builder.append(right);
		return builder.toString();
	}
}

